import { loginAsAdminOnce, waitForPageLoading, gotoHashPath, collectAppRoutes } from '../fixtures/auth-helpers.js'
import { pickSelectOption } from '../fixtures/form-helpers.js'

test('debug post-save v3', async ({ page }) => {
  page.on('console', (m) => {
    const t = m.text()
    if (t.includes('changeFormState') || t.includes('[detail]') || t.includes('无效详情')) {
      console.log('CONSOLE=' + t)
    }
  })
  page.on('request', (r) => {
    if (r.url().includes('/prefund/regulatorOrg/')) console.log('REQ=' + r.method() + ' ' + r.url() + ' ' + (r.postData() || '').slice(0, 200))
  })
  page.on('response', async (r) => {
    if (r.url().includes('/prefund/regulatorOrg/detail')) {
      const b = await r.json().catch(() => ({}))
      console.log('DETAIL_RESP=' + JSON.stringify({ s: r.status(), code: b.code, keys: b.data ? Object.keys(b.data).slice(0, 20) : null }))
    }
  })

  await loginAsAdminOnce(page)
  const routes = await collectAppRoutes(page)
  const listRoute = routes.find((r) => r.filePath === 'supervision/account/regulatorOrg/index' && !String(r.path).includes(':tableid'))
  await gotoHashPath(page, listRoute.path)
  await waitForPageLoading(page)
  await page.getByText('新增', { exact: true }).first().click()
  await waitForPageLoading(page)

  const ts = Date.now()
  await page.locator('input[placeholder="请输入机构名称"]').first().fill(`DBG3${ts}`)
  await page.locator('input[placeholder="请输入统一社会信用代码"]').first().fill(`91320500D3${String(ts).slice(-6)}`)
  await page.locator('input[placeholder="请输入行政区划编码"]').first().fill('320505')
  await pickSelectOption(page, page.locator('.detail-container'), '机构类型', '', { dictType: 'REGULATOR_ORG_TYPE' })

  await page.locator('[data-testid="detail-save-btn"]').first().click()
  await page.waitForEvent('framenavigated', { timeout: 15000 }).catch(() => null)
  await page.waitForTimeout(3000)

  console.log('HASH=' + page.url())
  const st = await page.evaluate(() => {
    const app = document.querySelector('#app')?.__vue__
    const walk = (c, d = 0) => {
      if (!c || d > 10) return null
      const f = c.form || (c.$data && c.$data.form)
      if (f && typeof f === 'object' && 'orgName' in f) return c
      for (const ch of c.$children || []) { const r = walk(ch, d + 1); if (r) return r }
      return null
    }
    const c = walk(app)
    return {
      formMode: c?.formMode, id: c?.getId ? c.getId() : null,
      orgName: c?.form?.orgName, orgCode: c?.form?.orgCode,
      hasDetailTpl: !!document.querySelector('.detail-template'),
      containerText: (document.querySelector('.detail-container')?.innerText || '').replace(/\s+/g, ' ').slice(0, 200)
    }
  })
  console.log('STATE=' + JSON.stringify(st))
})

