import { test } from '@playwright/test'
import { loginAsAdminOnce, waitForPageLoading, gotoHashPath, collectAppRoutes } from '../fixtures/auth-helpers.js'

test('debug add click no nav', async ({ page }) => {
  const errs = []
  page.on('console', (m) => {
    if (m.type() === 'error' || m.type() === 'warning') errs.push(m.type() + ': ' + m.text().slice(0, 300))
  })
  page.on('pageerror', (e) => errs.push('PAGEERROR: ' + e.message.slice(0, 300)))

  await loginAsAdminOnce(page)
  const routes = await collectAppRoutes(page)
  for (const fp of [
    'supervision/account/regulatoryAccountNew/index',
    'supervision/account/superviseAgreementNew/index',
    'supervision/account/mainAccount/index'
  ]) {
    const r = routes.find((x) => x.filePath === fp && !String(x.path).includes(':tableid'))
    console.log(`--- ${fp} route=${r?.path}`)
    await gotoHashPath(page, r.path)
    await waitForPageLoading(page)

    const btns = await page.evaluate(() =>
      [...document.querySelectorAll('button')]
        .filter((b) => b.innerText.trim() === '新增')
        .map((b) => ({
          text: b.innerText.trim(),
          cls: b.className,
          disabled: b.disabled,
          visible: !!(b.offsetWidth || b.offsetHeight),
          parentCls: b.parentElement?.className || ''
        }))
    )
    console.log('  ADD_BUTTONS=' + JSON.stringify(btns))

    // 直接调用组件的 handleAdd，看是否抛错
    const vmInfo = await page.evaluate(() => {
      const app = document.querySelector('#app')?.__vue__
      const walk = (c, d = 0) => {
        if (!c || d > 12) return null
        if (typeof c.handleAdd === 'function' && c.moduleName) return c
        for (const ch of c.$children || []) { const f = walk(ch, d + 1); if (f) return f }
        return null
      }
      const c = walk(app)
      if (!c) return { found: false }
      const out = {
        found: true,
        moduleName: c.moduleName,
        businessName: c.businessName,
        permsPrefix: c.permsPrefix || null,
        hasHandleAdd: typeof c.handleAdd === 'function'
      }
      try {
        c.handleAdd()
        out.callOk = true
      } catch (e) {
        out.callError = String(e && e.message)
        out.stack = String(e && e.stack).slice(0, 500)
      }
      return out
    })
    console.log('  VM=' + JSON.stringify(vmInfo))
    await page.waitForTimeout(2500)
    console.log('  URL_AFTER=' + page.url())
    console.log('  CONSOLE_ERRORS=' + JSON.stringify(errs.slice(-6)))
    errs.length = 0
  }
})

