import { test, expect } from '@playwright/test'
import { loginAsAdminOnce, waitForPageLoading, gotoHashPath, collectAppRoutes } from '../fixtures/auth-helpers.js'
import { pickSelectOption } from '../fixtures/form-helpers.js'

/**
 * 预售资金新页面（禅道 1413 账户管理 / 1415 监管协议）新增流程 UI 回归。
 *
 * 覆盖链路：菜单进入列表 → 点新增 → 填必填项 → 保存 → 跳详情并回显。
 * 弹窗选择类字段（监管机构/承办银行/开发项目等）通过直接写入表单模型赋值，
 * 只验证「保存 → 跳转 → 详情回显」这条主链路；弹窗自身的选择逻辑不在本 spec 范围。
 */

const CASE_ID = Date.now().toString().slice(-6)

async function openAddPage(page, filePath) {
  await loginAsAdminOnce(page)
  const routes = await collectAppRoutes(page)
  const listRoute = routes.find((r) => r.filePath === filePath && !String(r.path).includes(':tableid'))
  expect(listRoute, `菜单未注册：${filePath}`).toBeTruthy()
  await gotoHashPath(page, listRoute.path)
  await waitForPageLoading(page)

  await page.locator('button:has-text("新增")').first().click()
  await expect(page, '未跳转到新增页').toHaveURL(/formMode=add/, { timeout: 15000 })
  await waitForPageLoading(page)
  await expect(page.locator('.detail-container')).toBeVisible({ timeout: 15000 })
}

async function fillByPlaceholder(page, placeholder, value) {
  const input = page.locator(`input[placeholder="${placeholder}"]`).first()
  await expect(input, `未找到输入框「${placeholder}」`).toBeVisible({ timeout: 15000 })
  await input.fill(value)
}

/** 直接给详情页组件的 form 赋值（弹窗选择类字段用） */
async function setFormValues(page, patch) {
  await page.evaluate((p) => {
    const app = document.querySelector('#app').__vue__
    const walk = (c, d = 0) => {
      if (!c || d > 12) return null
      const f = c.form || (c.$data && c.$data.form)
      if (f && typeof f === 'object' && typeof c.submitForm === 'function') return c
      for (const ch of c.$children || []) {
        const r = walk(ch, d + 1)
        if (r) return r
      }
      return null
    }
    const vm = walk(app)
    if (!vm) throw new Error('未找到详情表单组件')
    Object.keys(p).forEach((k) => {
      vm.$set(vm.form, k, p[k])
    })
    vm.$forceUpdate && vm.$forceUpdate()
  }, patch)
}

/** 表单里必填但未填时点保存会校验拦下，这里先断言校验拦截存在 */
async function assertRequiredBlocking(page) {
  const saveBtn = page.locator('[data-testid="detail-save-btn"]').first()
  const target = (await saveBtn.count()) > 0 ? saveBtn : page.getByText('保存', { exact: true }).first()
  await target.click()
  await expect(page.locator('.el-form-item__error').first(), '空表单保存未被必填校验拦截').toBeVisible({
    timeout: 10000
  })
  await expect(page, '空表单保存后不应离开新增页').toHaveURL(/formMode=add/)
}

async function saveAndAssert(page, addApiFragment) {
  const saveRespPromise = page.waitForResponse(
    (r) => r.url().includes(addApiFragment) && r.request().method() === 'POST',
    { timeout: 30000 }
  )
  const saveBtn = page.locator('[data-testid="detail-save-btn"]').first()
  const target = (await saveBtn.count()) > 0 ? saveBtn : page.getByText('保存', { exact: true }).first()
  await target.click()

  const resp = await saveRespPromise
  const body = await resp.json().catch(() => ({}))
  expect(resp.status(), `保存接口 HTTP 异常：${body.msg || ''}`).toBe(200)
  expect(body.code, `保存失败：${body.msg || ''}`).toBe(200)
  expect(body.data, '保存未返回新主键').toBeTruthy()
  return String(body.data)
}

async function assertDetailRefilled(page, newId, detailApiFragment, expectedTexts) {
  await expect(page, '保存后未跳转到详情路由').toHaveURL(new RegExp(`${newId}\\?.*formMode=view`), {
    timeout: 20000
  })
  const detailResp = page
    .waitForResponse((r) => r.url().includes(detailApiFragment), { timeout: 20000 })
    .catch(() => null)
  await waitForPageLoading(page)
  const resp = await detailResp
  if (resp) {
    expect(resp.status(), '详情接口 HTTP 异常').toBe(200)
  }
  const container = page.locator('.detail-container')
  for (const text of expectedTexts) {
    await expect(container, `详情页未回显「${text}」`).toContainText(text, { timeout: 20000 })
  }
}

test.describe('预售资金新页面 UI 新增流程', () => {
  test('监管机构管理：空表单拦截 + 新增并回显', async ({ page }) => {
    const orgName = `自动化监管机构${CASE_ID}`
    await openAddPage(page, 'supervision/account/regulatorOrg/index')

    await assertRequiredBlocking(page)

    await fillByPlaceholder(page, '请输入机构名称', orgName)
    await fillByPlaceholder(page, '请输入统一社会信用代码', `91320500T${CASE_ID}00`)
    await fillByPlaceholder(page, '请输入行政区划编码', '320505')
    await pickSelectOption(page, page.locator('.detail-container'), '机构类型', '', {
      dictType: 'REGULATOR_ORG_TYPE'
